<style>
.hd-hero{background:linear-gradient(120deg,#213cb4,#4b20d0);color:#fff;padding:20px 24px;border-radius:16px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center;gap:12px}.hd-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}.hd-stat,.hd-box{background:#fff;border:1px solid #e1e5ee;border-radius:13px;padding:14px}.hd-stat b{font-size:1.5rem;color:#233bb0;display:block}.hd-filters{display:grid;grid-template-columns:minmax(220px,1fr) 190px auto;gap:10px;align-items:end}.hd-list{margin-top:12px}.hd-ticket{border:1px solid #e6e9f0;border-left:4px solid #5d75dd;border-radius:11px;padding:13px 15px;margin-bottom:9px;background:#fff}.hd-ticket[data-state="resuelto"],.hd-ticket[data-state="cerrado"]{border-left-color:#22a06b}.hd-detail-msg{background:#f4f6fb;padding:12px;border-radius:10px;margin:10px 0}.hd-status{min-width:155px}.hd-attachments a{display:inline-block;margin:3px}.hd-empty{padding:28px;text-align:center;color:#778299}.hd-actions{display:flex;gap:8px;flex-wrap:wrap}.hd-detail-layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(230px,.8fr);gap:18px}.hd-timeline{border-left:2px solid #dfe4ef;margin:8px 0 8px 7px;padding-left:16px}.hd-event{position:relative;margin-bottom:15px;font-size:.9rem}.hd-event:before{content:'';position:absolute;width:10px;height:10px;border-radius:50%;background:#4052a2;left:-22px;top:5px}.hd-event small{display:block;color:#788397;margin-top:3px}.hd-participant-select .ts-control{min-height:38px;border-color:#ced4da;border-radius:.375rem;padding:7px 10px}.hd-participant-select .ts-dropdown{z-index:1085!important}.hd-participant-select .ts-dropdown-content{max-height:220px!important}.hd-participant-select .option{white-space:normal;line-height:1.35;padding:8px 10px}@media(max-width:720px){.hd-stats{grid-template-columns:repeat(2,1fr)}.hd-filters{grid-template-columns:1fr}.hd-hero{align-items:flex-start;flex-direction:column}.hd-detail-layout{grid-template-columns:1fr}}
