<section class="hd-hero"><div><h2 class="mb-1"><i class="fa-solid fa-headset"></i> Help desk</h2><div>Atiende consultas y errores reportados por los operarios.</div></div><button class="btn btn-light" onclick="loadTickets()"><i class="fa-solid fa-rotate"></i> Actualizar</button></section>
<section class="hd-stats"><div class="hd-stat"><b id="sTotal">0</b>Total</div><div class="hd-stat"><b id="sPending">0</b>Pendientes</div><div class="hd-stat"><b id="sProcess">0</b>En proceso</div><div class="hd-stat"><b id="sNeed">0</b>Requieren información</div></section>
<section class="hd-box"><div class="hd-filters"><div><label class="form-label">Buscar</label><input id="search" class="form-control" placeholder="#, asunto u operario" oninput="renderTickets()"></div><div><label class="form-label">Estado</label><select id="filter" class="form-select" onchange="loadTickets()"><option value="">Todos</option><option value="pendiente">Pendientes</option><option value="en_proceso">En proceso</option><option value="requiere_info">Requiere información</option><option value="resuelto">Resueltos</option><option value="cerrado">Cerrados</option></select></div><div><label class="form-label">Tema</label><select id="category" class="form-select" onchange="renderTickets()"><option value="">Todos los temas</option><option>Producción</option><option>Ensamblaje</option><option>Empaquetado</option><option>Inventario</option><option>Acceso</option><option>Error del sistema</option><option>Otro</option></select></div></div><div class="hd-list" id="tickets"><div class="hd-empty">Cargando consultas…</div></div></section>
<div class="modal fade" id="ticketModal" tabindex="-1"><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title" id="detailTitle">Consulta</h5><div class="text-muted small" id="detailMeta"></div></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="hd-detail-layout"><section><h6><i class="fa-regular fa-comments"></i> Conversación</h6><div id="detailMessages"></div><form id="replyForm" class="mt-3"><label class="form-label">Responder</label><textarea class="form-control mb-2" name="mensaje" rows="4" required placeholder="Escribe una respuesta clara para el operario"></textarea><label class="form-label">Adjuntar captura (opcional)</label><input class="form-control mb-3" type="file" name="adjuntos[]" accept="image/jpeg,image/png,image/webp" multiple><button class="btn btn-primary"><i class="fa-solid fa-paper-plane"></i> Enviar respuesta</button></form></section><aside><h6><i class="fa-solid fa-list-check"></i> Seguimiento</h6><div id="detailTimeline" class="hd-timeline"></div><hr><h6><i class="fa-solid fa-users"></i> Participantes</h6><div id="detailParticipants" class="small mb-2"></div><div class="input-group mb-3"><select id="operatorSelect" class="form-select"><option value="">Cargando operarios…</option></select><button class="btn btn-outline-primary" type="button" onclick="addParticipant()">Agregar</button></div><hr><label for="detailStatus" class="fw-semibold mb-2">Actualizar estado</label><select id="detailStatus" class="form-select hd-status mb-2"><option value="pendiente">Pendiente</option><option value="en_proceso">En proceso</option><option value="requiere_info">Requiere información</option><option value="resuelto">Atendido</option><option value="cerrado">Cerrado</option></select><button class="btn btn-outline-primary w-100" onclick="saveStatus()">Guardar estado</button></aside></div></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
<script>
const api='controllers/helpdesk_api.php';let tickets=[],activeId=0;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const label=s=>String(s||'').replaceAll('_',' ');
async function req(url,opts={}){let r=await fetch(url,opts),j=await r.json();if(!j.success)throw Error(j.message||'No se pudo completar.');return j}
async function loadTickets(){try{let d=await req(api+'?action=list');tickets=d.tickets;let c={total:tickets.length,pending:tickets.filter(t=>t.estado==='pendiente').length,process:tickets.filter(t=>t.estado==='en_proceso').length,need:tickets.filter(t=>t.estado==='requiere_info').length};document.getElementById('sTotal').textContent=c.total;document.getElementById('sPending').textContent=c.pending;document.getElementById('sProcess').textContent=c.process;document.getElementById('sNeed').textContent=c.need;renderTickets()}catch(e){document.getElementById('tickets').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`}}
function renderTickets(){let q=document.getElementById('search').value.toLowerCase(),cat=document.getElementById('category').value,state=document.getElementById('filter').value;let rows=tickets.filter(t=>(!state||t.estado===state)&&(!cat||t.categoria===cat)&&(!q||`${t.id} ${t.titulo} ${t.solicitante_nombre}`.toLowerCase().includes(q)));document.getElementById('tickets').innerHTML=rows.length?rows.map(t=>`<article class="hd-ticket" data-state="${esc(t.estado)}"><div class="d-flex justify-content-between gap-3 align-items-start"><div><div class="fw-bold">#${t.id} · ${esc(t.titulo)}</div><div class="small text-muted mt-1">${esc(t.categoria)} · ${esc(t.solicitante_nombre)} · ${new Date(t.updated_at).toLocaleString('es-PE')}</div></div><div class="text-end"><span class="badge text-bg-light">${esc(label(t.estado))}</span><span class="badge ${t.prioridad==='urgente'?'text-bg-danger':'text-bg-secondary'}">${esc(t.prioridad)}</span></div></div><div class="hd-actions mt-2"><button class="btn btn-sm btn-outline-primary" onclick="openTicket(${t.id})"><i class="fa-regular fa-eye"></i> Ver conversación (${t.mensajes})</button></div></article>`).join(''):'<div class="hd-empty">No hay consultas con esos filtros.</div>'}
async function openTicket(id){try{let d=await req(api+`?action=detail&id=${id}`),t=d.ticket;activeId=id;document.getElementById('detailTitle').textContent=`#${t.id} · ${t.titulo}`;document.getElementById('detailMeta').textContent=`${t.solicitante_nombre} · ${t.categoria} · ${t.prioridad}`;document.getElementById('detailStatus').value=t.estado;document.getElementById('detailMessages').innerHTML=d.mensajes.map(m=>`<div class="hd-detail-msg"><div class="d-flex justify-content-between"><strong>${esc(m.autor_nombre)} ${m.actor_tipo==='usuario'?'<span class="badge text-bg-primary">Soporte</span>':''}</strong><small class="text-muted">${new Date(m.created_at).toLocaleString('es-PE')}</small></div><p class="mb-1 mt-2">${esc(m.mensaje).replace(/\n/g,'<br>')}</p><div class="hd-attachments">${(m.adjuntos||[]).map(a=>`<a class="btn btn-sm btn-light" target="_blank" href="${esc(a.url)}">📷 ${esc(a.nombre)}</a>`).join('')}</div></div>`).join('');document.getElementById('detailTimeline').innerHTML=(d.eventos||[]).map(ev=>`<div class="hd-event"><strong>${esc(label(ev.estado||'mensaje'))}</strong><div>${esc(ev.descripcion)}</div><small>${new Date(ev.created_at).toLocaleString('es-PE')} · ${esc(ev.actor_nombre)}</small></div>`).join('')||'<div class="text-muted">Sin actividad todavía.</div>';document.getElementById('detailParticipants').innerHTML=`<div><strong>${esc(t.solicitante_nombre)}</strong> <span class="text-muted">(solicitante)</span></div>`+(d.participantes||[]).map(p=>`<div>${esc(p.nombre_completo)}${p.cargo?` <span class="text-muted">· ${esc(p.cargo)}</span>`:''}</div>`).join('');let select=document.getElementById('operatorSelect');if(select.tomselect){select.tomselect.destroy()}let ops=await req(api+`?action=operators&id=${id}`);select.innerHTML='<option value="">Selecciona un operario…</option>'+ops.operarios.map(o=>`<option value="${o.id}">${esc(o.nombre_completo)}${o.cargo?` · ${esc(o.cargo)}`:''}</option>`).join('');select.disabled=!ops.operarios.length;if(window.TomSelect){new TomSelect(select,{placeholder:ops.operarios.length?'Buscar por nombre o cargo…':'No hay más operarios disponibles',searchField:['text'],maxOptions:8,dropdownParent:document.getElementById('ticketModal'),plugins:['clear_button'],render:{no_results:function(){return '<div class="no-results p-2">No se encontraron operarios</div>'}}});select.parentElement.classList.add('hd-participant-select')}bootstrap.Modal.getOrCreateInstance(document.getElementById('ticketModal')).show()}catch(e){alert(e.message)}}
document.getElementById('replyForm').onsubmit=async e=>{e.preventDefault();try{await req(api+`?action=reply&id=${activeId}`,{method:'POST',body:new FormData(e.target)});e.target.reset();await openTicket(activeId);loadTickets()}catch(x){alert(x.message)}};
async function saveStatus(){try{let f=new FormData();f.set('estado',document.getElementById('detailStatus').value);await req(api+`?action=status&id=${activeId}`,{method:'POST',body:f});await openTicket(activeId);loadTickets()}catch(e){alert(e.message)}}loadTickets();
async function addParticipant(){let select=document.getElementById('operatorSelect');if(!select.value){alert('Selecciona un operario para agregar.');return}try{let f=new FormData();f.set('operario_id',select.value);await req(api+`?action=add_participant&id=${activeId}`,{method:'POST',body:f});await openTicket(activeId);loadTickets()}catch(e){alert(e.message)}}
</script>
